import logging

from os import listdir, makedirs
from os.path import abspath, dirname, join, exists
from shutil import copy, move
from functools import wraps

python_logger = logging.getLogger("AdminApiLogger")


class AdminApiObject(dict):

    def __init__(self, data):
        for name, value in data.items():
            self[name] = self._wrap(value)

    def _wrap(self, value):
        return AdminApiObject(value) if isinstance(value, dict) else value

    def __getattr__(self, attr):
        return self[attr]

    def __setattr__(self, attr, value):
        self[attr] = value


def wrap_result(function):
    """Convert dict to AdminApiObject"""

    @wraps(function)
    def _wrap(inst, *args, **kw):
        result = function(inst, *args, **kw)
        if isinstance(result, list):
            return [AdminApiObject(item) for item in result]
        return AdminApiObject(result)
    return _wrap


def warn(message):
    """
    Function prints message into logger
    :param message: message to be printed
    """

    python_logger.log(logging.WARNING, message)


def save_disconnect_logs(target_file_name, logs_dir, leave_disconnect_logs):  # noqa: C901
    """
    Function copies disconnect logs to a given directory

    :param str target_file_name: target InfoModel filename.
    :param str logs_dir: debug_log_location (Admin_api.logs).
    :param bool leave_disconnect_logs: Admin CLI process saves current infomodel state at every connection break in
            "disconnect_xyz.ims2" files. collect_infomodel_log_from_current_session copy or move those files to
            directory of target_file_name. Copy or move depends on this parameter.
    """
    location_dir = abspath(dirname(logs_dir))
    target_dir = abspath(dirname(target_file_name))

    try:
        makedirs(target_dir, exist_ok=True)
    except Exception as e:
        logging.warning(f"Failed to create target directory '{target_dir}': {e}")
        return

    if not exists(location_dir):
        logging.warning(f"Source log directory does not exist: {location_dir}")
        return

    action = copy if leave_disconnect_logs else move
    try:
        for listed_file in listdir(location_dir):
            if 'disconnect' in listed_file and listed_file.endswith('ims2'):
                source_path = join(location_dir, listed_file)
                dest_path = join(target_dir, listed_file)
                try:
                    action(source_path, dest_path)
                    logging.info(f"{'Copied' if action == copy else 'Moved'}: {listed_file}")
                except Exception as file_err:
                    logging.warning(f"Unable to {action.__name__} file '{listed_file}': {file_err}")
    except Exception as dir_err:
        logging.error(f"Failed to list files in '{location_dir}': {dir_err}")


def search_recursively(d, searched_val):
    """
    search recursively for a key in a nested dict
    """
    result = None
    for k, v in d.items():
        if k == searched_val:
            return v
        if isinstance(v, list):
            result_list = [search_recursively(i, searched_val) for i in v]
            result = result_list[0] if len(result_list) > 0 else None
        elif isinstance(v, dict):
            result = search_recursively(v, searched_val)
    return result


def remove_brackets_from_end_of_string(string):
    """
    removes {,},[,] from string
    """
    if string[0] == "[" or string[0] == "(":
        string = string[1:]
    if string[-1] == "]" or string[-1] == ")":
        string = string[:-1]
    return string


def convert_str_with_integers_to_list_of_int(string, separator=","):
    """
    convert string like [1,2,3] to list
    """
    if isinstance(string, list):
        return string
    string = remove_brackets_from_end_of_string(string)
    splitted = string.split(separator)
    return_list = []
    for number in splitted:
        try:
            return_list.append(int(number))
        except (ValueError, TypeError):
            raise ValueError('Conversion error: Value (%s) is not a number e.g. 1, ${1}' % str(number))
    return return_list


def check_if_number_of_optional_args_is_divisible(is_multiple_of, optional_args):
    """
    checks if number of *optional_args is egual to is_equal or is multiple of is_multiple_of
    """
    if len(optional_args) % is_multiple_of:
        raise BaseException("Optional parameters mismatch. Should be multiple of {} but {} given."
                            .format(is_multiple_of, len(optional_args)))


def raise_value_error(param, value, subpage):
    msg = "Incorrect value of {param} parameter: {value}. " \
          "Please consult the documentation for appropriate value range: " \
          "https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/{subpage}".format(param=param,
                                                                                               value=value,
                                                                                               subpage=subpage)
    warn(msg)


class _CloseListener(object):

    ROBOT_LISTENER_API_VERSION = 2

    def __init__(self, callback):
        self._callback = callback

    def close(self):
        """Method called when library is out of scope."""
        try:
            if self._callback is not None:
                self._callback()
        except Exception as e:
            logging.warning('Exception was raised during library clean-up:\n{}'.format(str(e)))


def wrap_with_list(data):
    if not isinstance(data, list):
        return [data]
    else:
        return data
